  1573→// Voice response endpoint — candidate audio → Whisper transcription → AI response → TTS audio
  1574→router.post('/mock/:sessionId/voice-respond', authMiddleware, upload.single('audio'), async (req, res) => {
  1575→  try {
  1576→    const sessionId = req.params.sessionId;
  1577→
  1578→    // Get session
  1579→    const sessionResult = await pool.query(
  1580→      'SELECT * FROM mock_interview_sessions WHERE id = $1 AND user_id = $2 AND status = $3',
  1581→      [sessionId, req.user.id, 'in_progress']
  1582→    );
  1583→
  1584→    if (sessionResult.rows.length === 0) {
  1585→      return res.status(404).json({ error: 'Session not found or already completed' });
  1586→    }
  1587→
  1588→    const session = sessionResult.rows[0];
  1589→    const conversation = session.conversation || [];
  1590→    const questionIds = session.question_ids || [];
  1591→
  1592→    // Step 1: Transcribe audio with Whisper (with client-side SpeechRecognition fallback)
  1593→    // The client sends the live SpeechRecognition transcript alongside the audio as a fallback
  1594→    const clientTranscript = (req.body.response_text || '').trim();
  1595→    let transcribedText = '';
  1596→    let usedFallback = false;
  1597→
  1598→    if (req.file) {
  1599→      // Audio file uploaded as multipart — send buffer directly to Whisper
  1600→      const baseMime = (req.file.mimetype || 'audio/webm').split(';')[0];
  1601→      const ext = baseMime.includes('mp4') ? 'mp4' : baseMime.includes('ogg') ? 'ogg' : 'webm';
  1602→      console.log(`[voice-respond] Received file: ${req.file.size} bytes, mime: ${req.file.mimetype}, client transcript: ${clientTranscript.length} chars`);
  1603→
  1604→      const whisperFormData = new FormData();
  1605→      whisperFormData.append('file', req.file.buffer, {
  1606→        filename: `recording.${ext}`,
  1607→        contentType: baseMime
  1608→      });
  1609→      whisperFormData.append('model', 'whisper-1');
  1610→      whisperFormData.append('response_format', 'verbose_json');
  1611→
  1612→      const baseUrl = process.env.OPENAI_BASE_URL || 'https://api.openai.com/v1';
  1613→      const apiKey = process.env.OPENAI_API_KEY;
  1614→      const whisperHeaders = { 'Authorization': `Bearer ${apiKey}` };
  1615→      if (req.user.stripe_subscription_id) whisperHeaders['X-Subscription-ID'] = req.user.stripe_subscription_id;
  1616→
  1617→      try {
  1618→        const whisperRes = await fetch(`${baseUrl}/audio/transcriptions`, {
  1619→          method: 'POST',
  1620→          headers: whisperHeaders,
  1621→          body: whisperFormData
  1622→        });
  1623→        if (whisperRes.ok) {
  1624→          const whisperResult = await whisperRes.json();
  1625→          if (whisperResult && whisperResult.text) {
  1626→            transcribedText = whisperResult.text.trim();
  1627→            console.log(`[voice-respond] Whisper transcription: "${transcribedText.substring(0, 100)}..."`);
  1628→          }
  1629→        } else {
  1630→          const errText = await whisperRes.text();
  1631→          console.error('[voice-respond] Whisper API error:', whisperRes.status, errText);
  1632→          // BUG FIX: On 429 or other Whisper failure, use client-side SpeechRecognition transcript
  1633→          if (clientTranscript.length >= 10) {
  1634→            transcribedText = clientTranscript;
  1635→            usedFallback = true;
  1636→            console.log(`[voice-respond] Using client SpeechRecognition fallback: "${transcribedText.substring(0, 100)}..."`);
  1637→          }
  1638→        }
  1639→      } catch (whisperErr) {
  1640→        console.error('[voice-respond] Whisper call failed:', whisperErr.message);
  1641→        // BUG FIX: Use client transcript on Whisper failure
  1642→        if (clientTranscript.length >= 10) {
  1643→          transcribedText = clientTranscript;
  1644→          usedFallback = true;
  1645→          console.log(`[voice-respond] Using client SpeechRecognition fallback after error`);
  1646→        }
