   478→// Format date helper
   479→function formatDate(dateString) {
   480→  const date = new Date(dateString);
   481→  const now = new Date();
   482→  const diffMs = now - date;
   483→  const diffMins = Math.floor(diffMs / 60000);
   484→  const diffHours = Math.floor(diffMs / 3600000);
   485→  const diffDays = Math.floor(diffMs / 86400000);
   486→
   487→  if (diffMins < 1) return 'Just now';
   488→  if (diffMins < 60) return `${diffMins}m ago`;
   489→  if (diffHours < 24) return `${diffHours}h ago`;
   490→  if (diffDays < 7) return `${diffDays}d ago`;
   491→
   492→  return date.toLocaleDateString();
   493→}
