router.get('/mock/question-bank', authMiddleware, async (req, res) => {
  try {
    const { role } = req.query;

    let whereClause = '';
    const params = [];
    if (role) {
      params.push(role);
      whereClause = 'WHERE LOWER(role) = LOWER($1)';
    }

