      'Cache-Control': 'no-cache',
    });
    res.send(audioBuffer);
  } catch (err) {
    console.error('TTS endpoint error:', err);
    // Return 200 with fallback flag instead of crashing
    res.status(200).json({ tts_unavailable: true, text: req.body?.text || '' });
  }
});

