  // and attaches the already-obtained stream to the now-rendered video element.
  useEffect(() => {
    if (mockCameraReady && mockStreamRef.current && mockSession && mockSession.status === 'in_progress') {
      const v = mockVideoRef.current
      if (v && !v.srcObject) {
